# This function calculates factorial recursively
def factorial(n):
    # Base case: if n is 0 or 1, return 1
    if n <= 1:
        return 1
    else:
        # Recursive case: n multiplied by factorial of n-1
        return n * factorial(n - 1)

# Example usage
print(factorial(5))  # Output should be 120

